import {uid,clone,cubic} from './core.js';
import {flattenCubic} from './bezier.js';
const sub=(a,b)=>({x:a.x-b.x,y:a.y-b.y}),dot=(a,b)=>a.x*b.x+a.y*b.y,unit=(v,fallback={x:1,y:0})=>{const l=Math.hypot(v.x,v.y);return l>1e-12?{x:v.x/l,y:v.y/l}:fallback;},distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function generate(pts,parameters,t0,t1){const p0=pts[0],p3=pts.at(-1);let c00=0,c01=0,c11=0,x0=0,x1=0;for(let i=0;i<pts.length;i++){const t=parameters[i],s=1-t,b0=s*s*s,b1=3*s*s*t,b2=3*s*t*t,b3=t*t*t,a0={x:t0.x*b1,y:t0.y*b1},a1={x:-t1.x*b2,y:-t1.y*b2},v={x:pts[i].x-p0.x*(b0+b1)-p3.x*(b2+b3),y:pts[i].y-p0.y*(b0+b1)-p3.y*(b2+b3)};c00+=dot(a0,a0);c01+=dot(a0,a1);c11+=dot(a1,a1);x0+=dot(a0,v);x1+=dot(a1,v);}const det=c00*c11-c01*c01,len=distance(p0,p3);let al=Math.abs(det)>1e-12?(x0*c11-x1*c01)/det:len/3,ar=Math.abs(det)>1e-12?(c00*x1-c01*x0)/det:len/3;if(!Number.isFinite(al)||!Number.isFinite(ar)||al<len*1e-6||ar<len*1e-6)al=ar=len/3;al=Math.min(al,len*4+1e-9);ar=Math.min(ar,len*4+1e-9);return [{...p0,out:{x:p0.x+t0.x*al,y:p0.y+t0.y*al}},{...p3,in:{x:p3.x-t1.x*ar,y:p3.y-t1.y*ar}}];}
function error(pts,curve,u){let max=0,index=Math.floor(pts.length/2);for(let i=0;i<pts.length;i++){const e=distance(pts[i],cubic(...curve,u[i]));if(e>max){max=e;index=i;}}return {max,index};}
function reparameterize(curve,p,t){const [a,b]=curve,c=a.out||a,d=b.in||b,s=1-t,q=sub(cubic(a,b,t),p),v={x:3*s*s*(c.x-a.x)+6*s*t*(d.x-c.x)+3*t*t*(b.x-d.x),y:3*s*s*(c.y-a.y)+6*s*t*(d.y-c.y)+3*t*t*(b.y-d.y)},v2={x:6*s*(d.x-2*c.x+a.x)+6*t*(b.x-2*d.x+c.x),y:6*s*(d.y-2*c.y+a.y)+6*t*(b.y-2*d.y+c.y)},den=dot(v,v)+dot(q,v2);return Math.abs(den)<1e-12?t:Math.max(0,Math.min(1,t-dot(q,v)/den));}
export function fitCubics(points,t0,t1,tolerance=.5){const pts=points.filter((p,i)=>!i||distance(p,points[i-1])>1e-12),out=[];function fit(pts,t0,t1,depth){if(pts.length<2)return;const u=[0];let length=0;for(let i=1;i<pts.length;i++){length+=distance(pts[i],pts[i-1]);u.push(length);}for(let i=0;i<u.length;i++)u[i]/=length||1;let best=generate(pts,u,t0,t1),err=error(pts,best,u);for(let n=0;n<6;n++){for(let i=0;i<u.length;i++)u[i]=reparameterize(best,pts[i],u[i]);const curve=generate(pts,u,t0,t1),next=error(pts,curve,u);if(next.max>=err.max)break;best=curve;err=next;}if(err.max<=tolerance||pts.length===2||depth>=30){out.push(best);return;}const split=Math.max(1,Math.min(pts.length-2,err.index)),tc=unit(sub(pts[split+1],pts[split-1]),t0);fit(pts.slice(0,split+1),t0,tc,depth+1);fit(pts.slice(split),tc,t1,depth+1);}fit(pts,t0,t1,0);return out;}
export function simplifyCurves(o,tolerance=.5){if(!Number.isFinite(tolerance)||tolerance<=0)throw Error('Tolerancia inválida.');for(const sp of [o,...o.subpaths||[]]){const n=sp.nodes.length,count=n-(sp.closed?0:1);if(count<2)continue;const cuts=[0];for(let i=1;i<count;i++){const a=sp.nodes[i-1],b=sp.nodes[i],c=sp.nodes[(i+1)%n],incoming=unit(sub(b,b.in||a)),outgoing=unit(sub(b.out||c,b));if(dot(incoming,outgoing)<Math.cos(Math.PI/6))cuts.push(i);}cuts.push(count);const fitted=[];for(let j=1;j<cuts.length;j++){const points=[];for(let i=cuts[j-1];i<cuts[j];i++)points.push(...flattenCubic(sp.nodes[i],sp.nodes[(i+1)%n],Math.min(.03,tolerance/8)).slice(points.length?1:0));const first=sp.nodes[cuts[j-1]],second=sp.nodes[(cuts[j-1]+1)%n],last=sp.nodes[cuts[j]%n],prev=sp.nodes[(cuts[j]-1)%n],t0=unit(sub(first.out||second,first)),t1=unit(sub(last,last.in||prev));fitted.push(...fitCubics(points,t0,t1,tolerance*.8));}if(!fitted.length)continue;const nodes=[{...clone(fitted[0][0]),nid:sp.nodes[0].nid||uid()}];for(const [a,b] of fitted){nodes.at(-1).out=a.out;nodes.push({...clone(b),nid:uid()});}if(sp.closed){nodes[0].in=nodes.at(-1).in;nodes.pop();}else nodes.at(-1).nid=sp.nodes.at(-1).nid||uid();if(nodes.length<sp.nodes.length)sp.nodes=nodes;}return o;}
